import{_ as e,o as a,c as i,l as o,t as s,N as h}from"./chunks/framework.CMqbtke2.js";const f=JSON.parse('{"title":"git-patch-id | x-cmd man (git man1) | Compute unique ID for a patch","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-patch-id - Compute unique ID for a patch","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-patch-id | x-cmd man (git man1) | Compute unique ID for a patch"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-patch-id - Compute unique ID for a patch"}]]},"headers":[],"params":{"isMan":true,"man":"git-patch-id","category":"git man1","desc":"Compute unique ID for a patch"},"relativePath":"git/man1/git-patch-id.md","filePath":"git/man1/git-patch-id.md"}'),n={name:"git/man1/git-patch-id.md"},p={class:"visually-hidden"},c=h(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-patch-id - Compute unique ID for a patch</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> patch-id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--stable </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --unstable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> --verbatim]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Read a patch from the standard input and compute the patch ID for it.</p><p>A &quot;patch ID&quot; is nothing but a sum of SHA-1 of the file diffs associated with a patch, with line numbers ignored. As such, it&#39;s &quot;reasonably stable&quot;, but at the same time also reasonably unique, i.e., two patches that have the same &quot;patch ID&quot; are almost guaranteed to be the same thing.</p><p>The main usecase for this command is to look for likely duplicate commits.</p><p>When dealing with <em>git diff-tree</em> output, it takes advantage of the fact that the patch is prefixed with the object name of the commit, and outputs two 40-byte hexadecimal strings. The first string is the patch ID, and the second string is the commit ID. This can be used to make a mapping from patch ID to commit ID.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--verbatim</p><blockquote><p>Calculate the patch-id of the input as it is given, do not strip any whitespace.</p><blockquote><pre><code>This is the default if patchid.verbatim is true.
</code></pre></blockquote></blockquote><p>--stable</p><blockquote><p>Use a &quot;stable&quot; sum of hashes as the patch ID. With this option:</p><blockquote><p>·</p><p>Reordering file diffs that make up a patch does not affect the ID. In particular, two patches produced by comparing the same two trees with two different settings for &quot;-O&lt;orderfile&gt;&quot; result in the same patch ID signature, thereby allowing the computed result to be used as a key to index some meta-information about the change between the two trees;</p></blockquote><blockquote><p>·</p><p>Result is different from the value produced by git 1.9 and older or produced when an &quot;unstable&quot; hash (see --unstable below) is configured - even when used on a diff output taken without any use of &quot;-O&lt;orderfile&gt;&quot;, thereby making existing databases storing such &quot;unstable&quot; or historical patch-ids unusable.</p></blockquote><blockquote><p>·</p><p>All whitespace within the patch is ignored and does not affect the id.</p><blockquote><pre><code>This is the default if patchid.stable is set to true.
</code></pre></blockquote></blockquote></blockquote><p>--unstable</p><blockquote><p>Use an &quot;unstable&quot; hash as the patch ID. With this option, the result produced is compatible with the patch-id value produced by git 1.9 and older and whitespace is ignored. Users with pre-existing databases storing patch-ids produced by git 1.9 and older (who do not deal with reordered patches) may want to use this option.</p><blockquote><pre><code>This is the default.
</code></pre></blockquote></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,18);function r(t,d,u,l,m,g){return a(),i("div",null,[o("h1",p,s(t.$params.man),1),c])}const k=e(n,[["render",r]]);export{f as __pageData,k as default};
